package com.oms.order.service;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;
class OrderAutoReviewServiceTest {
    OrderAllocationServiceTest fixture;OrderRepository repository;OrderAutoReviewService service;JdbcTemplate db;
    @BeforeAll static void setup(){OrderAllocationServiceTest.setup();}
    @BeforeEach void seed(){db=OrderAllocationServiceTest.db;db.update("DELETE FROM oms_order_review_event");db.update("DELETE FROM oms_order_review_config");db.update("DELETE FROM oms_order_auto_allocation");fixture=new OrderAllocationServiceTest();fixture.seed();repository=(OrderRepository)ReflectionTestUtils.getField(fixture.service,"repository");service=new OrderAutoReviewService();ReflectionTestUtils.setField(service,"repository",repository);ReflectionTestUtils.setField(service,"catalog",fixture.catalog);db.update("UPDATE oms_order SET review_status='PENDING',review_decision='UNASSESSED',review_by='',review_policy='MANUAL',review_at=NULL");}
    Map<String,Object> p(){Map<String,Object> p=OrderAutoReviewPolicy.defaults();p.put("mode","AUTO");return p;}
    void configure(Map<String,Object> p){db.update("INSERT INTO oms_order_review_config(company_code,channel_id,policy_json) VALUES ('VERIFY',1,?) ON DUPLICATE KEY UPDATE policy_json=VALUES(policy_json),revision=revision+1",encode(p));}
    String state(){return db.queryForObject("SELECT review_decision FROM oms_order WHERE id=?",String.class,fixture.id);}
    void evaluate(){new TransactionTemplate(new DataSourceTransactionManager(db.getDataSource())).execute(status->{OrderAutoReviewService.evaluate(repository,"VERIFY",fixture.id,false,"test");return null;});}
    long n(String sql){return db.queryForObject(sql,Long.class);}
    @Test void defaultManualDoesNotUseRetiredPullSetting(){db.update("UPDATE oms_order_pull_config SET review_mode='AUTO'");evaluate();assertEquals("MANUAL_REQUIRED",state());assertEquals("MANUAL",((Map<?,?>)service.configuration("VERIFY",1).get("policy")).get("mode"));}
    @Test void previewDoesNotWriteOrTriggerAllocation(){configure(p());long version=n("SELECT control_version FROM oms_order");assertEquals("AUTO_APPROVED",service.preview("VERIFY",fixture.id).get("decision"));assertEquals(version,n("SELECT control_version FROM oms_order"));assertEquals(0,n("SELECT COUNT(*) FROM oms_order_review_event"));assertEquals(0,n("SELECT COUNT(*) FROM oms_order_auto_allocation"));verifyNoInteractions(fixture.warehouse);}
    @Test void stockProgressCanApproveWaitingOrderAndCreateAutomaticAllocationTask(){Map<String,Object> p=p();p.put("stock_condition","FULL_RESERVED");configure(p);db.update("UPDATE oms_order_line SET reserved_quantity=0");evaluate();assertEquals("WAIT_STOCK",state());Map<String,Object> allocation=fixture.config();allocation.put("execution_mode","AUTO");db.update("UPDATE oms_order_allocation_config SET policy_json=?",encode(allocation));db.update("UPDATE oms_order_line SET reserved_quantity=10");evaluate();assertEquals("AUTO_APPROVED",state());assertEquals(1,n("SELECT COUNT(*) FROM oms_order_auto_allocation"));assertEquals(2,n("SELECT COUNT(*) FROM oms_order_review_event"));}
    @Test void manualHitRemainsManualAfterStockAndRuleChanges(){Map<String,Object> p=p();p.put("stock_condition","FULL_RESERVED");p.put("quantity_enabled",1);p.put("quantity_threshold",10);configure(p);db.update("UPDATE oms_order_line SET reserved_quantity=0");evaluate();assertEquals("MANUAL_REQUIRED",state());configure(p());db.update("UPDATE oms_order_line SET reserved_quantity=10");evaluate();assertEquals("MANUAL_REQUIRED",state());assertEquals(1,n("SELECT COUNT(*) FROM oms_order_review_event"));}
    @Test void humanApprovalKeepsOriginalHitsAndCannotBeOverwritten(){Map<String,Object> p=p();p.put("quantity_enabled",1);p.put("quantity_threshold",10);configure(p);evaluate();String snapshot=db.queryForObject("SELECT review_snapshot FROM oms_order",String.class);OrderReviewService human=new OrderReviewService();ReflectionTestUtils.setField(human,"repository",repository);Map<String,Object> body=fixture.row("orders",Arrays.asList(fixture.row("id",fixture.id,"control_version",1)),"reason","已核对大件数订单");assertEquals(true,human.apply("VERIFY","approve",body,"tester").get(0).get("success"));assertEquals("HUMAN_APPROVED",state());configure(p());evaluate();assertEquals("HUMAN_APPROVED",state());assertEquals(snapshot,db.queryForObject("SELECT review_snapshot FROM oms_order",String.class));assertEquals(1,n("SELECT COUNT(*) FROM oms_order_review_event WHERE action='HUMAN_APPROVE'"));assertThrows(IllegalArgumentException.class,()->service.recheck("VERIFY",fixture.id,2,"tester"));}
    @Test void humanApprovalRequiresNoteAndStillRejectsPlatformBlock(){OrderReviewService human=new OrderReviewService();ReflectionTestUtils.setField(human,"repository",repository);Map<String,Object> body=fixture.row("orders",Arrays.asList(fixture.row("id",fixture.id,"control_version",0)),"reason","");assertEquals(false,human.apply("VERIFY","approve",body,"tester").get(0).get("success"));body.put("reason","checked");db.update("UPDATE oms_platform_order SET fulfillment_block_reason='refund'");assertEquals(false,human.apply("VERIFY","approve",body,"tester").get(0).get("success"));assertEquals(0,n("SELECT COUNT(*) FROM oms_order_review_event"));}
    @Test void explicitRecheckIsVersionedAndCompanyScoped(){configure(p());assertThrows(IllegalArgumentException.class,()->service.recheck("OTHER",fixture.id,0,"tester"));assertThrows(IllegalArgumentException.class,()->service.recheck("VERIFY",fixture.id,999,"tester"));assertEquals(0,n("SELECT COUNT(*) FROM oms_order_review_event"));service.recheck("VERIFY",fixture.id,0,"tester");assertEquals("AUTO_APPROVED",state());}
    @Test void localRollbackDoesNotPublishApprovalOrAllocationTask(){configure(p());Map<String,Object> allocation=fixture.config();allocation.put("execution_mode","AUTO");db.update("UPDATE oms_order_allocation_config SET policy_json=?",encode(allocation));TransactionTemplate tx=new TransactionTemplate(new DataSourceTransactionManager(db.getDataSource()));assertThrows(IllegalStateException.class,()->tx.execute(status->{OrderAutoReviewService.evaluate(repository,"VERIFY",fixture.id,false,"test");throw new IllegalStateException("rollback");}));assertEquals("UNASSESSED",state());assertEquals(0,n("SELECT COUNT(*) FROM oms_order_review_event"));assertEquals(0,n("SELECT COUNT(*) FROM oms_order_auto_allocation"));}
    @Test void corruptRulesFailClosedWithoutChangingReview(){db.update("INSERT INTO oms_order_review_config(company_code,channel_id,policy_json) VALUES ('VERIFY',1,?)",encode(Collections.singletonMap("mode","UNKNOWN")));assertThrows(IllegalArgumentException.class,this::evaluate);assertEquals("PENDING",db.queryForObject("SELECT review_status FROM oms_order",String.class));}
    @Test void ruleSaveChecksVersionAndSkuOwnership(){service.save("VERIFY",fixture.row("channel_id",1,"revision",0,"policy",p()),"tester");assertThrows(IllegalArgumentException.class,()->service.save("VERIFY",fixture.row("channel_id",1,"revision",0,"policy",p()),"tester"));Map<String,Object> p=p();p.put("review_skus",Arrays.asList("UNKNOWN"));when(fixture.catalog.goods("VERIFY",Arrays.asList("UNKNOWN"))).thenReturn(Collections.emptyMap());assertThrows(IllegalArgumentException.class,()->service.save("VERIFY",fixture.row("channel_id",1,"revision",1,"policy",p),"tester"));assertEquals(1,n("SELECT revision FROM oms_order_review_config"));}
    @Test void sameSkuAcrossLinesCountsTotalPieces(){Map<String,Object> p=p();p.put("quantity_enabled",1);p.put("quantity_threshold",15);configure(p);db.update("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,reserved_quantity,payment) VALUES ('VERIFY',?,'second','A','A',5,5,0)",fixture.id);Map<String,Object> preview=service.preview("VERIFY",fixture.id);assertEquals("MANUAL_REQUIRED",preview.get("decision"));assertEquals(15,number((Map<String,Object>)preview.get("facts"),"quantity"));}
    @Test void unchangedAssessmentDoesNotDuplicateEvents(){configure(p());db.update("UPDATE oms_order_line SET reserved_quantity=0");Map<String,Object> p=p();p.put("stock_condition","FULL_RESERVED");configure(p);evaluate();evaluate();assertEquals(1,n("SELECT COUNT(*) FROM oms_order_review_event"));}
    @Test void concurrentRechecksApproveOnce() throws Exception {configure(p());ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<Boolean>> results=new ArrayList<>();for(int i=0;i<2;i++)results.add(pool.submit(()->{try{service.recheck("VERIFY",fixture.id,0,"test");return true;}catch(IllegalArgumentException e){return false;}}));int successes=0;for(Future<Boolean> f:results)if(f.get(10,TimeUnit.SECONDS))successes++;assertEquals(1,successes);assertEquals(1,n("SELECT COUNT(*) FROM oms_order_review_event"));}finally{pool.shutdownNow();}}
}
